   *the input card info and withdraw status
   *and number should be cleared*/
  ejectCard(): boolean {
    /*Definition Start*/
    let boolCardIDValidated: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () => this.CardIDValidated === true,
            description: "self.CardIDValidated=true",
          }),
        description: "self.CardIDValidated=true",
        then: l({
          logic: () => true,
          description: "true",
        }),
        else: l({
          logic: () => false,
          description: "false",
        }),
      })
      .build().pass;
    let boolPasswordValidated: boolean = l()
      .if({
        logic: () =>
          l({
            logic: () => this.PasswordValidated === true,
            description: "self.PasswordValidated=true",
          }),
        description: "self.PasswordValidated=true",
        then: l({
          logic: () => true,
          description: "true",
        }),
        else: l({
          logic: () => false,
          description: "false",
        }),
      })
      .build().pass;
    let existCard: BankCard = l({
      logic: () =>
        getRepository(BankCard).find(
          (c: any) =>
            l({
              logic: () => c === this.InputCard,
              description: "c=self.InputCard",
            }).build().pass,
        ),
      description: "BankCard.allInstance()->any(c|c=self.InputCard)",
    }).build().pass;
