        execute: () => (clearCard.CardID = 0),
        description: "clearCard.CardID=0",
      })
      .and({
        execute: () => (clearCard.CardStatus = CardStatus.NORMAL),
        description: "clearCard.CardStatus=CardStatus::NORMAL",
      })
      .and({
        execute: () => (clearCard.Catalog = CardCatalog.DESPOSIT),
        description: "clearCard.Catalog=CardCatalog::DESPOSIT",
      })
      .and({
        execute: () => (clearCard.Password = 0),
        description: "clearCard.Password=0",
      })
      .and({
        execute: () => (clearCard.Balance = 0),
        description: "clearCard.Balance=0",
      })
      .and({
        execute: () => (clearCard.BelongedUser = undefined),
        description: "clearCard.BelongedUser=null",
      })
      .and({
        execute: () => getRepository(BankCard).push(clearCard),
        description: "BankCard.allInstance()->includes(clearCard)",
      })
      .and({
        execute: () => true,
        description: "result=true",
      })
      .build().value;
    /*Postcondition End*/
  }
}
export { AutomatedTellerMachineSystem_AutoGenerated };

